#!/usr/bin/env bash
set -euo pipefail
repo_dir=$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd); cd "$repo_dir"; tmp_dir=$(mktemp -d); api_pid=""; web_pid=""; cleanup(){ [[ -n "$web_pid" ]] && kill "$web_pid" 2>/dev/null || true; [[ -n "$api_pid" ]] && { pkill -TERM -P "$api_pid" 2>/dev/null || true; kill "$api_pid" 2>/dev/null || true; }; }; trap cleanup EXIT
wrangler="$repo_dir/node_modules/.bin/wrangler"; for db in CONTROL_DB HOTEL_DEMO_DB HOTEL_SECOND_DB; do CI=1 "$wrangler" d1 migrations apply "$db" --local -c apps/api/wrangler.jsonc >/dev/null; done
CI=1 "$wrangler" d1 execute CONTROL_DB --local -c apps/api/wrangler.jsonc --command "INSERT OR REPLACE INTO control_hotels VALUES ('hotel-a','hotel-a','HOTEL_DEMO_DB',1),('hotel-b','hotel-b','HOTEL_SECOND_DB',1); INSERT OR REPLACE INTO hotel_admin_metadata(hotel_id,name,address,plan_tier) VALUES ('hotel-a','Hotel A','A Street','FREE'),('hotel-b','Hotel B','B Street','FREE'); INSERT OR REPLACE INTO access_identity_mappings VALUES ('subject-a','a@test.com',1),('subject-network','network@test.com',1); INSERT OR REPLACE INTO hotel_memberships VALUES ('subject-a','hotel-a','admin',1); INSERT OR REPLACE INTO network_memberships VALUES ('subject-network','saas_admin',1);" >/dev/null
"$wrangler" dev --local --ip 127.0.0.1 --port 8787 --var LOCAL_DEV_AUTH:true -c apps/api/wrangler.jsonc >"$tmp_dir/api.log" 2>&1 & api_pid=$!; for _ in {1..30}; do curl -fsS http://127.0.0.1:8787/health >/dev/null 2>&1 && break; sleep 1; done
"$repo_dir/node_modules/.bin/vite" --host 127.0.0.1 --port 4174 --config apps/web/vite.config.ts >"$tmp_dir/web.log" 2>&1 & web_pid=$!; for _ in {1..30}; do curl -fsS http://127.0.0.1:4174/users >/dev/null 2>&1 && break; sleep 1; done
mkdir -p output/playwright; pwcli="${CODEX_HOME:-$HOME/.codex}/skills/playwright/scripts/playwright_cli.sh"; bash "$pwcli" -s cf-i07-admin open about:blank >/dev/null; bash "$pwcli" -s cf-i07-admin run-code --filename scripts/cf-i07-browser-regression.playwright.js; bash "$pwcli" -s cf-i07-admin close >/dev/null; echo "CF-I07 admin responsive browser regression PASS"
